    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # The rows form repeating horizontal patterns. Infer the shortest period
    # consistent with the observed row, then color its predicted foreground cells.
    for r, row in enumerate(grid):
        last = max((c for c, v in enumerate(row) if v == fg), default=-1)
        if last < 0 or last == w - 1:
            continue
        n = last + 1
        period = None
        for p in range(1, n):
            if all(row[i] == row[i % p] for i in range(n)):
                period = p
                break
        if period is not None:
            for c in range(n, w):
                if row[c % period] == fg:
